public static class Solution
{
    public static Dictionary<string, int> WordCounts(string text)
    {
        var counts = new Dictionary<string, int>();
        var word = new StringBuilder();
        void Flush()
        {
            if (word.Length == 0) return;
            string w = word.ToString();
            counts[w] = counts.GetValueOrDefault(w) + 1;
            word.Clear();
        }
        foreach (char c in text.ToLowerInvariant())
        {
            if (char.IsLetter(c) || c == '\'') word.Append(c);
            else Flush();
        }
        Flush();
        return counts;
    }

    public static List<List<string>> GroupAnagrams(IEnumerable<string> words)
    {
        var groups = new Dictionary<string, List<string>>();
        var order = new List<string>();
        foreach (string w in words)
        {
            char[] letters = w.ToLowerInvariant().ToCharArray();
            Array.Sort(letters);
            string key = new string(letters);
            if (!groups.TryGetValue(key, out var group))
            {
                group = new List<string>();
                groups[key] = group;
                order.Add(key);
            }
            group.Add(w);
        }
        var result = new List<List<string>>();
        foreach (string key in order) result.Add(groups[key]);
        return result;
    }

    public static char? FirstRepeated(string text)
    {
        var seen = new HashSet<char>();
        foreach (char c in text)
        {
            if (!seen.Add(c)) return c;
        }
        return null;
    }

    public static Dictionary<string, List<string>> Invert(Dictionary<string, string> owners)
    {
        var result = new Dictionary<string, List<string>>();
        foreach (var (item, owner) in owners)
        {
            if (!result.TryGetValue(owner, out var items))
            {
                items = new List<string>();
                result[owner] = items;
            }
            items.Add(item);
        }
        foreach (var items in result.Values) items.Sort(StringComparer.Ordinal);
        return result;
    }
}

unitTests:
Test("word counts", () =>
{
    var c = WordCounts("The cat and THE hat. Don't stop, don't!");
    CheckEq(c["the"], 2);
    CheckEq(c["don't"], 2);
    CheckEq(c["hat"], 1);
    CheckEq(c.Count, 6);
    CheckEq(WordCounts("  ...  ").Count, 0);
});

Test("anagram groups", () =>
{
    var g = GroupAnagrams(["tea", "eat", "tan", "ate", "nat", "bat"]);
    CheckEq(g.Count, 3);
    CheckEq(g[0], new[] { "tea", "eat", "ate" });
    CheckEq(g[1], new[] { "tan", "nat" });
    CheckEq(g[2], new[] { "bat" });
    CheckEq(GroupAnagrams(["Listen", "silent"])[0], new[] { "Listen", "silent" });
    CheckEq(GroupAnagrams([]).Count, 0);
});

Test("first repeated character", () =>
{
    CheckEq(FirstRepeated("swiss"), (char?)'s');
    CheckEq(FirstRepeated("abcb a"), (char?)'b');
    CheckEq(FirstRepeated("abc"), (char?)null);
    CheckEq(FirstRepeated(""), (char?)null);
});

Test("inverting a dictionary", () =>
{
    var owners = new Dictionary<string, string> { ["pen"] = "ada", ["mug"] = "bob", ["cup"] = "ada", ["Book"] = "ada" };
    var inv = Invert(owners);
    CheckEq(inv.Count, 2);
    CheckEq(inv["ada"], new[] { "Book", "cup", "pen" });
    CheckEq(inv["bob"], new[] { "mug" });
    CheckEq(owners.Count, 4);
});

